// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count all Friday the 13ths in a full 400-year cycle.

var earliest = DateOnly.MinValue;

// Scan from 0001-01-01 forward for the first Friday the 13th
for (var d = new DateOnly(1, 1, 13); d.Year == 1; d = d.AddMonths(1))
{
    if (d.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = d;
        break;
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest.DayOfWeek})");

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var byMonth = new int[12];

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            byMonth[month - 1]++;
        }
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();
Console.WriteLine("Distribution by month:");
for (int m = 0; m < 12; m++)
{
    var name = new DateOnly(2000, m + 1, 1).ToString("MMMM");
    Console.WriteLine($"  {name,-12} {byMonth[m],3}");
}

// Which day-of-week lands on the 13th most often?
Console.WriteLine();
Console.WriteLine("13th-of-month frequency by day of week:");
var byDay = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        byDay[(int)d.DayOfWeek]++;
    }
}

foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-12} {byDay[(int)dow],3}");
"}

